input.proposed_solution:
debounce() never cancelled the previously scheduled call, so every call fired. Keep the pending timer handle, clear it on each new call and reset it when the timer fires. Added a burst test (three calls → one invocation with the last arguments).

Patch (already applied in the repository snapshot):
```diff
--- a/src/debounce.js
+++ b/src/debounce.js
@@ -9,8 +9,15 @@
  */
 export function debounce(fn, waitMs, timers = {}) {
   const setTimer = timers.setTimer ?? ((cb, ms) => setTimeout(cb, ms));
+  const clearTimer = timers.clearTimer ?? ((h) => clearTimeout(/** @type {ReturnType<typeof setTimeout>} */ (h)));
+  /** @type {unknown} */
+  let pending;
   /** @param {A} args */
   return (...args) => {
-    setTimer(() => fn(...args), waitMs);
+    if (pending !== undefined) clearTimer(pending);
+    pending = setTimer(() => {
+      pending = undefined;
+      fn(...args);
+    }, waitMs);
   };
 }
--- a/test/debounce.test.js
+++ b/test/debounce.test.js
@@ -20,3 +20,14 @@
   t.flush();
   assert.deepEqual(calls, [1]);
 });
+
+test("only the last call in a burst fires", () => {
+  const t = fakeTimers();
+  const calls = [];
+  const d = debounce((x) => calls.push(x), 100, t);
+  d(1);
+  d(2);
+  d(3);
+  t.flush();
+  assert.deepEqual(calls, [3]);
+});
```
